#pragma once
#include "five_point.hpp"
namespace ms::five {
// 143B68060 / 143B683A0 / 143B68E50 / 143BA4AF0, build 21287.
struct SturmPolynomial{int degree;std::array<double,13> c{};};
inline double evaluate(const SturmPolynomial&p,double x){double y=p.c[p.degree];for(int i=p.degree-1;i>=0;--i)y=y*x+p.c[i];return y;}
inline SturmPolynomial remainder(const SturmPolynomial&a,const SturmPolynomial&b){auto r=a;int d=a.degree-b.degree;if(b.c[b.degree]<0){for(int i=d-1;i>=0;i-=2)r.c[i]=-r.c[i];for(int k=d;k>=0;--k)for(int j=b.degree+k-1;j>=k;--j)r.c[j]=-r.c[j]-r.c[b.degree+k]*b.c[j-k];}else{for(int k=d;k>=0;--k)for(int j=b.degree+k-1;j>=k;--j)r.c[j]=r.c[j]-r.c[b.degree+k]*b.c[j-k];}r.degree=b.degree-1;while(r.degree>0&&std::abs(r.c[r.degree])<1.e-12)r.c[r.degree--]=0;return r;}
inline int variations(const std::vector<SturmPolynomial>&s,double x,int infinity=0){int n=0;double previous=0;bool first=true;for(auto&p:s){double v=infinity?p.c[p.degree]:evaluate(p,x);if(infinity<0&&(p.degree&1))v=-v;if(!first&&(previous==0||previous*v<0))++n;previous=v;first=false;}return n;}
inline bool regula(const SturmPolynomial&p,double lo,double hi,double&root){double fl=evaluate(p,lo),fh=evaluate(p,hi);if(fl*fh>0)return false;if(std::abs(fl)<1.e-14){root=lo;return true;}if(std::abs(fh)<1.e-14){root=hi;return true;}double previous=fl;for(int i=0;i<800;++i){double x=(fh*lo-fl*hi)/(fh-fl),f=evaluate(p,x);if(std::abs(std::abs(x)>1.e-14?f/x:f)<1.e-14){root=x;return true;}if(f*fl>=0){lo=x;fl=f;if(f*previous>0)fh=fh*.5;}else{hi=x;fh=f;if(f*previous>0)fl=fl*.5;}previous=f;}return false;}
inline void isolate(const std::vector<SturmPolynomial>&s,double lo,double hi,int vl,int vh,double*out){int count=vl-vh;if(count<=0)return;if(count==1&&regula(s[0],lo,hi,*out))return;double mid=0;for(int i=0;i<800;++i){mid=(lo+hi)*.5;int vm=variations(s,mid);if(count==1){if(std::abs(mid)>1.e-14?std::abs((hi-lo)/mid)<1.e-14:std::abs(hi-lo)<1.e-14){*out=mid;return;}if(vl==vm)lo=mid;else hi=mid;}else{if(vl==vm)lo=mid;else if(vm==vh)hi=mid;else{isolate(s,lo,mid,vl,vm,out);isolate(s,mid,hi,vm,vh,out+vl-vm);return;}}}std::fill(out,out+count,mid);}
inline std::vector<double> real_roots(const Poly&coeff){SturmPolynomial p{10};std::copy(coeff.begin(),coeff.end(),p.c.begin());while(p.degree>0&&p.c[p.degree]==0)--p.degree;if(p.degree==0)return {};std::vector<SturmPolynomial>s{p};SturmPolynomial derivative{p.degree-1};double factor=std::abs(p.degree*p.c[p.degree]);for(int i=0;i<p.degree;++i)derivative.c[i]=(i+1)*p.c[i+1]/factor;s.push_back(derivative);while(s.back().degree>0){auto r=remainder(s[s.size()-2],s.back());if(r.degree==0){r.c[0]=-r.c[0];s.push_back(r);break;}double f=-std::abs(r.c[r.degree]);for(int i=0;i<=r.degree;++i)r.c[i]=r.c[i]/f;s.push_back(r);}
 int vl=variations(s,0,-1),vh=variations(s,0,1);if(vl<=vh)return {};double lo=-1,hi=1;int actual=0;for(int i=0;i<32;++i){actual=variations(s,lo);if(actual==vl)break;lo=lo*10;}vl=variations(s,lo);for(int i=0;i<32;++i){actual=variations(s,hi);if(actual==vh)break;hi=hi*10;}vh=variations(s,hi);if(vl<=vh)return {};std::vector<double> roots(vl-vh);isolate(s,lo,hi,vl,vh,roots.data());return roots;
}
inline double ascending(const Poly&p,double x){double value=p[0]+0.,power=1;for(int i=1;i<11;++i){power=power*x;value=value+power*p[i];}return value;}
inline std::vector<std::array<double,9>> candidates(const Algebra&a,const std::vector<double>&roots){std::vector<std::array<double,9>> result;for(double z:roots){double den=ascending(a.den,z),x=ascending(a.nx,z)/den,y=ascending(a.ny,z)/den;std::array<double,9>e;for(int i=0;i<9;++i)e[i]=y*a.basis[54+i]+x*a.basis[45+i]+z*a.basis[63+i]+a.basis[72+i];result.push_back(e);}return result;}
inline std::vector<std::array<double,9>> solve(const double*a,const double*b){auto polynomial=algebra(a,b);return candidates(polynomial,real_roots(polynomial.polynomial));}
}
